sql.if:
AND (
       t1.lang_mtcd             = #{langMtcd}
    OR t1.lang_mtcd             IS NULL            
)

mapper.sql:
SELECT t4.medata_set_id , m2.prpty_nm , m3.val , ROW_NUMBER() OVER(PARTITION BY t4.medata_set_id ORDER BY m2.sort_odrg) AS sort_odrg FROM dtmeta.tb_meta_dataset t4 INNER JOIN dtmeta.tb_meta_model t5 ON t4.model_id = t5.model_id INNER JOIN ( SELECT t7.model_prpty_id , t7.model_id , t2.prpty_nm , ROW_NUMBER() OVER(ORDER BY t7.model_prpty_sort_odrg, t2.prpty_sort_odrg) AS sort_odrg FROM dtmeta.tb_meta_modelproperty t7 INNER JOIN dtmeta.tb_meta_property t2 ON t2.prpty_id = t7.prpty_id AND t2.prpty_data_sttus_mtcd = 'use' WHERE t7.model_prpty_del_yn = 'N'
/* 메타 모델 - 프라퍼티 */ UNION ALL SELECT concat('MP_', t5.model_id) , t5.model_id , 'metaModel' , -1 FROM dtmeta.tb_meta_model t5 WHERE 1=1
/* 메타 유형 모델 */ UNION ALL SELECT concat('TypeMP_', t5.model_id) , t5.model_id , 'metaTypeModel' , -2 FROM dtmeta.tb_meta_model t5 WHERE 1=1
) m2 ON t5.model_id = m2.model_id LEFT OUTER JOIN ( SELECT t1.medata_set_id , t1.model_prpty_id , t2.prpty_nm , CASE WHEN t6.data_type_mtcd = 'langString' THEN jsonb_build_object('language', t1.lang_mtcd, 'value', t1.medata_val) WHEN t6.data_type_mtcd = 'geoJson' THEN dtmeta.ST_AsGeoJson(t1.geodata_val)::jsonb WHEN t6.data_type_mtcd in ('json', 'address', 'dataInfo') THEN t1.medata_val::jsonb ELSE to_jsonb(t1.medata_val) END AS val FROM dtmeta.tb_meta_data t1 INNER JOIN dtmeta.tb_meta_property t2 ON t1.prpty_id = t2.prpty_id AND t2.prpty_data_sttus_mtcd = 'use' INNER JOIN dtmeta.tb_meta_dataset t4 ON t1.medata_set_id = t4.medata_set_id INNER JOIN dtmeta.tb_meta_model t5 ON t4.model_id = t5.model_id INNER JOIN dtmeta.tb_meta_model t6 ON t1.val_model_id = t6.model_id WHERE t2.data_array_yn = 'N'
/* 배열 내용은 10건 이하만 */ UNION ALL SELECT t1.medata_set_id , MAX(t1.model_prpty_id) AS model_prpty_id , t2.prpty_nm , jsonb_agg(t3.val ORDER BY t3.medata_id) AS val FROM dtmeta.tb_meta_data t1 INNER JOIN dtmeta.tb_meta_property t2 ON t1.prpty_id = t2.prpty_id AND t2.prpty_data_sttus_mtcd = 'use' LEFT JOIN ( SELECT ROW_NUMBER() OVER(PARTITION BY t1.medata_set_id, t1.prpty_id ORDER BY t1.medata_id) AS rn , t1.medata_id , t1.medata_set_id , t1.prpty_id , CASE WHEN t6.data_type_mtcd = 'langString' THEN jsonb_build_object('language', t1.lang_mtcd, 'value', t1.medata_val) WHEN t6.data_type_mtcd = 'geoJson' THEN dtmeta.ST_AsGeoJson(t1.geodata_val)::jsonb WHEN t6.data_type_mtcd in ('json', 'address', 'dataInfo') THEN t1.medata_val::jsonb ELSE to_jsonb(t1.medata_val) END AS val FROM dtmeta.tb_meta_data t1 INNER JOIN dtmeta.tb_meta_property t2 ON t1.prpty_id = t2.prpty_id AND t2.prpty_data_sttus_mtcd = 'use' INNER JOIN dtmeta.tb_meta_model t6 ON t1.val_model_id = t6.model_id WHERE t2.data_array_yn = 'Y' ) t3 ON t1.medata_id = t3.medata_id INNER JOIN dtmeta.tb_meta_dataset t4 ON t1.medata_set_id = t4.medata_set_id INNER JOIN dtmeta.tb_meta_model t5 ON t4.model_id = t5.model_id WHERE t2.data_array_yn = 'Y'
AND t3.rn <= COALESCE(#{arrayDataLimit}, 10)
GROUP BY t1.medata_set_id, t2.prpty_nm /* 메타 모델 */ UNION ALL SELECT t4.medata_set_id , concat('MP_', t4.model_id) , 'metaModel' , to_jsonb(t5.model_nm) FROM dtmeta.tb_meta_dataset t4 INNER JOIN dtmeta.tb_meta_model t5 ON t4.model_id = t5.model_id WHERE 1=1
/* 메타 유형 모델 */ UNION ALL SELECT t4.medata_set_id , concat('TypeMP_', t4.model_id) , 'metaTypeModel' , to_jsonb(t8.model_nm) FROM dtmeta.tb_meta_dataset t4 INNER JOIN dtmeta.tb_meta_model t5 ON t4.model_id = t5.model_id INNER JOIN dtmeta.tb_meta_model t8 ON t5.type_model_id = t8.model_id WHERE 1=1
) m3 ON t4.medata_set_id = m3.medata_set_id AND m2.model_prpty_id = m3.model_prpty_id WHERE 1=1

mapper.select:
SELECT /* SQL_ID: MetadataApiMapper.selectMetadataListBySetPropertyNm */ row_to_json(x1) AS metaJsonStr FROM ( SELECT CASE WHEN t3.data_type_mtcd = 'langString' THEN jsonb_build_object('language', t1.lang_mtcd, 'value', t1.medata_val) WHEN t3.data_type_mtcd = 'geoJson' THEN dtmeta.ST_AsGeoJson(t1.geodata_val)::jsonb WHEN t3.data_type_mtcd in ('json', 'address', 'dataInfo') THEN t1.medata_val::jsonb ELSE to_jsonb(t1.medata_val) END AS "medataVal" , t5.medata_set_nm AS "medataValNm" , CASE WHEN t3.model_type_mtcd = 'object_type' THEN #{resourceUrl} || t1.medata_val ELSE NULL END AS url , t1.medata_id AS "medataId" FROM dtmeta.tb_meta_data t1 INNER JOIN dtmeta.tb_meta_property t2 ON t1.prpty_id = t2.prpty_id AND t2.prpty_data_sttus_mtcd = 'use' INNER JOIN dtmeta.tb_meta_model t3 ON t1.val_model_id = t3.model_id LEFT OUTER JOIN dtmeta.tb_meta_dataset t5 ON t1.medata_val = t5.medata_set_id WHERE t2.prpty_nm = #{prptyNm} AND t1.medata_set_id = #{medataSetId} AND (t1.medata_val IS NOT NULL OR t1.geodata_val IS NOT NULL)
AND EXISTS ( SELECT a1.medata_set_id FROM dtmeta.tb_meta_dataset a1 INNER JOIN dtmeta.tb_meta_model a2 ON a1.model_id = a2.model_id WHERE a1.medata_set_id = t1.medata_set_id AND a2.type_model_id = #{typeModelId} )
) x1

mapper.sql:
WITH cte_baseSets AS ( SELECT t4.medata_set_id , (t5.type_model_id = 'DigitalTwin' AND #{objectRefFormat} = 'object') AS expand , t4.medata_set_amd_dt FROM dtmeta.tb_meta_dataset t4 JOIN dtmeta.tb_meta_model t5 ON t4.model_id = t5.model_id WHERE 1=1
), cte_refFilterOwners AS (
SELECT DISTINCT t1.medata_set_id AS owner_set_id FROM dtmeta.tb_meta_data t1 JOIN dtmeta.tb_meta_property t2 ON t1.prpty_id = t2.prpty_id AND t2.prpty_data_sttus_mtcd = 'use' JOIN dtmeta.tb_meta_model t6 ON t1.val_model_id = t6.model_id JOIN cte_baseSets bs ON bs.medata_set_id = t1.medata_set_id WHERE t6.model_type_mtcd = 'object_type'
SELECT bs.medata_set_id AS owner_set_id FROM cte_baseSets bs
), cte_pagedSets AS ( SELECT bs.medata_set_id , bs.expand FROM cte_baseSets bs WHERE EXISTS ( SELECT 1 FROM cte_refFilterOwners rfo WHERE rfo.owner_set_id = bs.medata_set_id ) ORDER BY bs.medata_set_amd_dt DESC, bs.medata_set_id DESC
)

, cte_refIds AS ( SELECT DISTINCT t1.medata_val AS ref_id , t1.medata_set_id AS owner_set_id , (ps.expand OR #{hasDtwObjsAttr}) AS owner_expand , ROW_NUMBER() OVER(PARTITION BY t1.medata_set_id, t1.prpty_id ORDER BY t1.medata_id) AS ref_rn FROM dtmeta.tb_meta_data t1 INNER JOIN dtmeta.tb_meta_property t2 ON t1.prpty_id = t2.prpty_id AND t2.prpty_data_sttus_mtcd = 'use' INNER JOIN dtmeta.tb_meta_model t6 ON t1.val_model_id = t6.model_id INNER JOIN cte_pagedSets ps ON ps.medata_set_id = t1.medata_set_id WHERE (ps.expand OR #{hasDtwObjsAttr}) AND t6.model_type_mtcd = 'object_type'
AND t2.prpty_nm = #{dtwObjsAttr}
)

, cte_mainRows AS ( SELECT t4.medata_set_id , m2.prpty_nm , m2.sort1 , m2.sort2 , m2.model_prpty_id , CASE WHEN m3.model_type_mtcd != 'object_type' THEN m3.val WHEN ( ps.expand OR (#{hasDtwObjsAttr} AND m2.prpty_nm = #{dtwObjsAttr}) ) THEN CASE WHEN m2.data_array_yn = 'N' THEN COALESCE(oj.obj_json::jsonb, m3.val) ELSE ( SELECT jsonb_agg(COALESCE(oj2.obj_json::jsonb, to_jsonb(elem_text)) ORDER BY ord) FROM jsonb_array_elements_text(m3.val) WITH ORDINALITY AS e(elem_text, ord) LEFT JOIN cte_objJsons oj2 ON ( ps.expand OR (#{hasDtwObjsAttr} AND m2.prpty_nm = #{dtwObjsAttr}) ) AND oj2.medata_set_id = elem_text ) END WHEN #{objectRefFormat} = 'id' THEN m3.val ELSE null END AS val FROM cte_pagedSets ps JOIN dtmeta.tb_meta_dataset t4 ON t4.medata_set_id = ps.medata_set_id JOIN dtmeta.tb_meta_model t5 ON t4.model_id = t5.model_id INNER JOIN ( SELECT t7.model_prpty_id , t7.model_id , t2.prpty_nm , t2.data_array_yn , t7.model_prpty_sort_odrg AS sort1 , t2.prpty_sort_odrg AS sort2 FROM dtmeta.tb_meta_modelproperty t7 INNER JOIN dtmeta.tb_meta_property t2 ON t2.prpty_id = t7.prpty_id AND t2.prpty_data_sttus_mtcd = 'use' WHERE t7.model_prpty_del_yn = 'N'
) m2 ON t5.model_id = m2.model_id LEFT OUTER JOIN ( SELECT t1.medata_set_id , t1.model_prpty_id , t2.prpty_nm , CASE WHEN t6.data_type_mtcd = 'langString' THEN jsonb_build_object('language', t1.lang_mtcd, 'value', t1.medata_val) WHEN t6.data_type_mtcd = 'geoJson' THEN dtmeta.ST_AsGeoJson(t1.geodata_val)::jsonb WHEN t6.data_type_mtcd in ('json', 'address', 'dataInfo') THEN t1.medata_val::jsonb ELSE to_jsonb(t1.medata_val) END AS val , t1.medata_val AS val_text , t2.data_array_yn , t6.model_type_mtcd FROM dtmeta.tb_meta_data t1 INNER JOIN dtmeta.tb_meta_property t2 ON t1.prpty_id = t2.prpty_id AND t2.prpty_data_sttus_mtcd = 'use' INNER JOIN dtmeta.tb_meta_model t6 ON t1.val_model_id = t6.model_id WHERE t2.data_array_yn = 'N' AND t1.medata_set_id IN (SELECT medata_set_id FROM cte_pagedSets)
/* 배열 내용은 10건 이하만 */ UNION ALL SELECT t1.medata_set_id , MAX(t1.model_prpty_id) AS model_prpty_id , t2.prpty_nm , jsonb_agg(t3.val ORDER BY t3.medata_id) AS val , NULL AS val_text , 'Y' AS data_array_yn , MAX(t3.model_type_mtcd) AS model_type_mtcd FROM dtmeta.tb_meta_data t1 INNER JOIN dtmeta.tb_meta_property t2 ON t1.prpty_id = t2.prpty_id AND t2.prpty_data_sttus_mtcd = 'use' LEFT JOIN ( SELECT ROW_NUMBER() OVER(PARTITION BY t1.medata_set_id, t1.prpty_id ORDER BY t1.medata_id) AS rn , t1.medata_id , t1.medata_set_id , t1.prpty_id , t6.model_type_mtcd , CASE WHEN t6.data_type_mtcd = 'langString' THEN jsonb_build_object('language', t1.lang_mtcd, 'value', t1.medata_val) WHEN t6.data_type_mtcd = 'geoJson' THEN dtmeta.ST_AsGeoJson(t1.geodata_val)::jsonb WHEN t6.data_type_mtcd in ('json', 'address', 'dataInfo') THEN t1.medata_val::jsonb ELSE to_jsonb(t1.medata_val) END AS val FROM dtmeta.tb_meta_data t1 INNER JOIN dtmeta.tb_meta_property t2 ON t1.prpty_id = t2.prpty_id AND t2.prpty_data_sttus_mtcd = 'use' INNER JOIN dtmeta.tb_meta_model t6 ON t1.val_model_id = t6.model_id WHERE t2.data_array_yn = 'Y' ) t3 ON t1.medata_id = t3.medata_id WHERE t2.data_array_yn = 'Y' AND t1.medata_set_id IN (SELECT medata_set_id FROM cte_pagedSets)
AND t3.rn <= COALESCE(#{arrayDataLimit}, 10)
GROUP BY t1.medata_set_id, t2.prpty_nm ) m3 ON t4.medata_set_id = m3.medata_set_id AND m2.model_prpty_id = m3.model_prpty_id LEFT OUTER JOIN cte_objJsons oj ON ( ps.expand OR (#{hasDtwObjsAttr} AND m2.prpty_nm = #{dtwObjsAttr}) ) AND m3.model_type_mtcd = 'object_type' AND m2.data_array_yn = 'N' AND oj.medata_set_id = m3.val_text WHERE 1=1
AND NOT ( m3.model_type_mtcd = 'object_type' AND NOT ( ps.expand OR (#{hasDtwObjsAttr} AND m2.prpty_nm = #{dtwObjsAttr}) ) )
)

mapper.select:
/* SQL_ID: MetadataApiMapper.selectMetadataSetCountForApi */ WITH cte_baseSets AS ( SELECT t4.medata_set_id , (t5.type_model_id = 'DigitalTwin' AND #{objectRefFormat} = 'object') AS expand , t4.medata_set_amd_dt FROM dtmeta.tb_meta_dataset t4 JOIN dtmeta.tb_meta_model t5 ON t4.model_id = t5.model_id WHERE 1=1
), cte_refFilterOwners AS (
SELECT DISTINCT t1.medata_set_id AS owner_set_id FROM dtmeta.tb_meta_data t1 JOIN dtmeta.tb_meta_property t2 ON t1.prpty_id = t2.prpty_id AND t2.prpty_data_sttus_mtcd = 'use' JOIN dtmeta.tb_meta_model t6 ON t1.val_model_id = t6.model_id JOIN cte_baseSets bs ON bs.medata_set_id = t1.medata_set_id WHERE t6.model_type_mtcd = 'object_type'
SELECT bs.medata_set_id AS owner_set_id FROM cte_baseSets bs
) SELECT COUNT(*) FROM cte_baseSets bs WHERE EXISTS ( SELECT 1 FROM cte_refFilterOwners rfo WHERE rfo.owner_set_id = bs.medata_set_id )
